private static final int MOD = 1003;

public int countWays(String expr) {
    int[] res = solve(expr, 0, expr.length() - 1);
    return res[0] % MOD; // res[0] = true ways, res[1] = false ways
}

// returns {trueWays, falseWays} for operands i..j
private int[] solve(String expr, int i, int j) {
    if (i == j) {
        if (expr.charAt(i) == 'T') {
            return new int[]{1, 0};
        }
        return new int[]{0, 1};
    }
    int trueWays = 0, falseWays = 0;
    for (int k = i + 1; k < j; k += 2) {
        char op = expr.charAt(k);
        int[] left = solve(expr, i, k - 1);
        int[] right = solve(expr, k + 1, j);
        int lt = left[0], lf = left[1], rt = right[0], rf = right[1];
        if (op == '&') {
            trueWays += lt * rt;
            falseWays += lt * lf + lf * rt + lf * rf;
        } else if (op == '|') {
            trueWays += lt * rt + lt * rf + lf * rt;
            falseWays += lf * rf;
        } else { // '^'
            trueWays += lt * rf + lf * rt;
            falseWays += lt * rt + lf * rf;
        }
        trueWays %= MOD;
        falseWays %= MOD;
    }
    return new int[]{trueWays, falseWays};
}

