private static final int MOD = 1003;

public int countWays(String expr) {
    int n = expr.length();
    int[][][] memo = new int[n][n][]; // memo[i][j] == null until computed
    return solve(expr, 0, n - 1, memo)[0] % MOD;
}

private int[] solve(String expr, int i, int j, int[][][] memo) {
    if (i == j) {
        return expr.charAt(i) == 'T' ? new int[]{1, 0} : new int[]{0, 1};
    }
    if (memo[i][j] != null) {
        return memo[i][j];
    }
    int trueWays = 0, falseWays = 0;
    for (int k = i + 1; k < j; k += 2) {
        char op = expr.charAt(k);
        int[] L = solve(expr, i, k - 1, memo);
        int[] R = solve(expr, k + 1, j, memo);
        int lt = L[0], lf = L[1], rt = R[0], rf = R[1];
        if (op == '&') {
            trueWays += lt * rt;
            falseWays += lt * lf + lf * rt + lf * rf;
        } else if (op == '|') {
            trueWays += lt * rt + lt * rf + lf * rt;
            falseWays += lf * rf;
        } else {
            trueWays += lt * rf + lf * rt;
            falseWays += lt * rt + lf * rf;
        }
        trueWays %= MOD;
        falseWays %= MOD;
    }
    memo[i][j] = new int[]{trueWays, falseWays};
    return memo[i][j];
}

