private static final int MOD = 1003;

public int countWays(String expr) {
    int n = expr.length();
    int[][] T = new int[n][n];
    int[][] F = new int[n][n];
    for (int i = 0; i < n; i += 2) { // operands at even indices
        if (expr.charAt(i) == 'T') {
            T[i][i] = 1;
        } else {
            F[i][i] = 1;
        }
    }
    for (int len = 2; len < n; len += 2) {     // span more operands
        for (int i = 0; i + len < n; i += 2) {
            int j = i + len;
            for (int k = i + 1; k < j; k += 2) {
                char op = expr.charAt(k);
                int lt = T[i][k - 1], lf = F[i][k - 1];
                int rt = T[k + 1][j], rf = F[k + 1][j];
                if (op == '&') {
                    T[i][j] = (T[i][j] + lt * rt) % MOD;
                    F[i][j] = (F[i][j] + lt * lf + lf * rt + lf * rf) % MOD;
                } else if (op == '|') {
                    T[i][j] = (T[i][j] + lt * rt + lt * rf + lf * rt) % MOD;
                    F[i][j] = (F[i][j] + lf * rf) % MOD;
                } else {
                    T[i][j] = (T[i][j] + lt * rf + lf * rt) % MOD;
                    F[i][j] = (F[i][j] + lt * rt + lf * rf) % MOD;
                }
            }
        }
    }
    return T[0][n - 1] % MOD;
}

